from lib import *
S = SS('f87')
R = J('f87'); ct = R['count']; lt = R['lat']
l0, l1, l5 = lt['0'], lt['0.001'], lt['0.005']
steps = [
    step(f"同一个页面(列出 100 个作者各有几本书),用 g 给每个请求计数、放进 X-Query-Count 响应头:/bad(逐个访问 a.books){ct['/bad']} 条,/good(selectinload){ct['/good']} 条;N+1 也可以藏在模板里:/tpl-bad 视图里没有循环,是模板里的 a.books|length 触发的,同样 {ct['/tpl-bad']} 条;多对一同理,/books-bad 里逐本书访问 b.author 也是 {ct['/books-bad']} 条。", b=bars([['/bad', ct['/bad'], str(ct['/bad'])], ['/tpl-bad', ct['/tpl-bad'], str(ct['/tpl-bad'])], ['/books-bad', ct['/books-bad'], str(ct['/books-bad'])], ['/good', ct['/good'], str(ct['/good'])]], 101, mark=[0, 1, 2], done=[3]), t=tl(S(1)), mark=lidx(S(1), '/bad', '/tpl-bad', '/books-bad'), done=lidx(S(1), '/good', '/tpl-good'), kv=KV([['/bad', f"{ct['/bad']} 条 = 1 + 100"], ['/good', f"{ct['/good']} 条"], ['藏在模板里', '同样 101 条']], ['/bad'])),
    step("SQLALCHEMY_RECORD_QUERIES = True 之后,get_recorded_queries() 里每条记录有语句、耗时,还有 location——发出这条语句的那一行代码(这里是 f87.py:71 · where):第一条是 SELECT author,后两条 SELECT book... 都指向同一行循环。看到同一个 location 重复很多次就是 N+1。(location 靠 Flask(...) 的 import_name 匹配调用栈,模块名对不上时是 <unknown>,我第一次运行就遇到了。)", t=tl(S(2)), done=lidx(S(2), 'SELECT'), kv=KV([['record_queries', '每条 SQL 的耗时与代码位置'], ['同一 location 重复', 'N+1 的迹象']], ['record_queries'])),
    step("开发期把漏掉的预加载变成错误:查询加 options(raiseload('*')),访问任何没预加载的关系都抛 InvalidRequestError「'Author.books' is not available due to lazy='raise'」,N+1 在写代码时就暴露,而不是上线后才发现慢。", t=tl(S(3)), mark=lidx(S(3), 'InvalidRequestError'), kv=KV([["raiseload('*')", '所有关系都不允许懒加载']], ["raiseload('*')"])),
    step(f"数据库在别的机器上时 N+1 被放大:在应用与 PostgreSQL 之间放一个加固定延迟的 TCP 代理(每个方向每个数据块各加一次延迟)。单向 0 ms:/bad {l0[0]:.1f} ms、/good {l0[1]:.1f} ms({l0[0] / l0[1]:.1f} 倍);1 ms:{l1[0]:.1f} ms 对 {l1[1]:.1f} ms({l1[0] / l1[1]:.1f} 倍);5 ms:{l5[0]:.0f} ms 对 {l5[1]:.1f} ms({l5[0] / l5[1]:.1f} 倍)。(一条查询可能不止一次往返,所以每条语句多出的时间比 2 倍单向延迟更大。)", b=bars([['0 ms /bad', l0[0], f'{l0[0]:.0f} ms'], ['1 ms /bad', l1[0], f'{l1[0]:.0f} ms'], ['5 ms /bad', l5[0], f'{l5[0]:.0f} ms'], ['5 ms /good', l5[1], f'{l5[1]:.0f} ms']], l5[0], mark=[0, 1, 2], done=[3]), t=tl(S(4)), mark=lidx(S(4), '1 ms', '5 ms'), done=lidx(S(4), '0 ms'), kv=KV([['无延迟', f'{l0[0] / l0[1]:.1f} 倍'], ['单向 1 ms', f'{l1[0] / l1[1]:.1f} 倍'], ['单向 5 ms', f'{l5[0] / l5[1]:.1f} 倍']], ['单向 5 ms'])),
    step("测试里守住查询数:给页面设一个阈值(这里 3 条),/good 是 2 条通过,/bad 是 101 条失败。把它写成断言放进测试,N+1 回归就会被 CI 拦下。", t=tl(S(5)), done=lidx(S(5), '通过'), mark=lidx(S(5), '失败'), kv=KV([['/good', '2 ≤ 3 通过'], ['/bad', '101 > 3 失败']], ['/bad'])),
]
A = mkartf('f87', 87, 'Flask,SQLAlchemy,N+1,性能,真实验证,动画演示',
    f'实测 N+1 查询:列 100 个作者的页面 {ct["/bad"]} 条 SQL 对 {ct["/good"]} 条、藏在模板里的 N+1、RECORD_QUERIES 找出发 SQL 的代码行、raiseload 在开发期报错、加了单向 5 ms 延迟的代理后 {l5[0]:.0f} ms 对 {l5[1]:.1f} ms、测试里断言查询数。',
    'N+1 到底有多慢?怎么发现它藏在哪一行、哪个模板里?数据库不在本机时会放大多少?这篇用真实的 PostgreSQL 和一个加了延迟的 TCP 代理,把这些量出来。',
    [(f'{ct["/bad"]} → {ct["/good"]}', '同一个页面的 SQL 条数:逐个懒加载与 selectinload'), (f'{l5[0] / l5[1]:.0f} 倍', '单向 5 ms 延迟下 /bad 与 /good 的耗时比'), ('location', 'RECORD_QUERIES 记录的发出 SQL 的代码位置')],
    [('数条数', '<p>上一篇:<a href="flask-joinedload-selectinload.html">joinedload() 与 selectinload()</a>;下一篇:<a href="flask-identity-map.html">SQLAlchemy Identity Map</a>。</p>'), ('找到发 SQL 的那一行', None), ('用 raiseload 提前暴露', None), ('网络延迟放大 N+1', '<p>延迟代理是本篇自己用 asyncio 写的,只是模拟「数据库不在本机」,不代表某个真实网络的数字。</p>'), ('用测试守住', None)],
    steps, [ENV_F + '。Flask-SQLAlchemy 3.1.1、psycopg 3.3.6、自己起的 PostgreSQL(非默认端口)与一个自写的延迟 TCP 代理', '没有验证:真实跨机房网络下的数字、连接池耗尽时 N+1 的并发表现、ORM 之外(如 GraphQL 解析器)里的 N+1、dataloader 这类批处理方案'], 'N+1 查询问题', panels=[('t', 'term', '实验输出'), ('b', 'bars', '条数 / 耗时'), ('kv', 'kv', '要点')])
